import math

def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau_n_12(n):
    if n == 1:
        return 1

    # Get the prime factorization of n: n = p1^e1 * p2^e2 * ...
    factors = prime_factorization(n)

    # tau(n^12) = (12*e1 + 1) * (12*e2 + 1) * ...
    tau = 1
    for exponent in factors.values():
        tau *= (12 * exponent + 1)
    return tau

def solve_and_verify(limit=1000):
    print("--- Verification of Known Candidates (1, 13, 25, 325) ---")
    candidates = [1, 13, 25, 325]
    for n in candidates:
        result = tau_n_12(n)
        print(f"n={n}: tau(n^12) = {result}. Match? {n == result}")

    print("\n--- Brute Force Search up to N = {} ---".format(limit))
    solutions = []
    for n in range(1, limit + 1):
        if n == tau_n_12(n):
            solutions.append(n)

    print("\n--- Solutions Found ---")
    print(solutions)

    # Report new solutions found in the range [1, 1000]
    known_solutions = {1, 13, 25, 325}
    new_solutions = [n for n in solutions if n not in known_solutions]

    if new_solutions:
        print(f"\n*** NEW SOLUTIONS FOUND: {new_solutions} ***")
    else:
        print("\nNo new solutions found beyond the known set in the tested range.")

# Run the function
solve_and_verify(1000)
